<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { useAuthStore } from '@/stores/auth'; import { Lock, User, ArrowRight } from '@element-plus/icons-vue'
const router = useRouter(); const auth = useAuthStore(); const loading = ref(false); const form = reactive({ loginName: 'admin', password: '123456' })
async function submit() { if (!form.loginName || !form.password) return ElMessage.warning('请输入账号和密码'); loading.value = true; try { await auth.login('admin', form); router.replace('/admin/dashboard') } catch (error) { ElMessage.error(error instanceof Error ? error.message : '登录失败') } finally { loading.value = false } }
</script>
<template><div class="login-screen"><div class="login-screen__visual"><div class="login-orbit login-orbit--one"></div><div class="login-orbit login-orbit--two"></div><div class="login-visual-copy"><span class="eyebrow">FROZEN SEAFOOD TRACEABILITY</span><h1>每一箱海产，<br><em>都有迹可循。</em></h1><p>从捕捞到餐桌，连接每一个冷链节点，<br>让数据成为产品可信的证据。</p><div class="login-visual-stats"><div><strong>39</strong><span>业务接口</span></div><div><strong>4</strong><span>流通节点</span></div><div><strong>24h</strong><span>全程可追</span></div></div></div><div class="login-wave"></div></div><div class="login-screen__panel"><div class="login-form-wrap"><div class="login-brand"><span class="brand-mark__symbol">F</span><div><strong>FSTS</strong><small>冷链溯源中枢</small></div></div><div class="login-heading"><span class="eyebrow">ADMIN CONSOLE</span><h2>欢迎回来</h2><p>登录管理端，查看冷链业务全貌。</p></div><el-form :model="form" size="large" @submit.prevent="submit"><el-form-item><el-input v-model="form.loginName" placeholder="管理员账号" :prefix-icon="User" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="登录密码" :prefix-icon="Lock" @keyup.enter="submit" /></el-form-item><el-button type="primary" class="login-submit" :loading="loading" @click="submit">进入管理端 <el-icon><ArrowRight /></el-icon></el-button></el-form><div class="login-switch">企业用户？<router-link to="/enterprise/login">切换到企业端登录</router-link></div><p class="login-note">默认账号：admin / 123456</p></div></div></div></template>
